"""Create the review page from actual authored assets and saved-scene captures."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'development/levels/hollow-creek'
r=json.loads((OUT/'authored-surfaces.json').read_text(encoding='utf-8'))
v=json.loads((ROOT/'development/levels/verification/hollow-creek-authored-surfaces.json').read_text(encoding='utf-8'))
page=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Camp Hollow Creek — authored surface review</title><style>body{background:#151d1c;color:#e4e7df;font:17px/1.6 system-ui;max-width:1250px;margin:auto;padding:28px}a{color:#a8d2c2}h1,h2{color:#e7d2a0}img{width:100%;height:auto}figure{margin:8px 0 24px}figcaption{padding:7px}.compare{display:grid;grid-template-columns:1fr 1fr;gap:16px}.gate{border-left:4px solid #ba9a60;padding:12px;background:#27332c}@media(max-width:750px){.compare{grid-template-columns:1fr}}</style><h1>Camp Hollow Creek</h1><p>24 October 2026 · Third authored surface pass</p><p class="gate">14 model families,30 fitted instances. Part-aligned timber grain, restrained mottling, lower-edge damp/dirt, exposed-surface fade, sparse oxidation, corner wear and fireplace-mouth soot. Existing curves stay smooth and flat faces stay flat. These are actual native/studio captures, not gameplay screenshots.</p>']
page+=['<h2>Same cameras, current scene</h2><p>The left image is the previous refined source; the right is the authored surface pass. Terrain, model shape, pivots and placement are unchanged.</p>']
for current in v['captures']:
    filename=Path(current['path']).name;previous=filename.replace('authored-','refined-')
    page.append(f'<div class="compare"><figure><img loading="lazy" src="../previews/hollow-creek/{previous}" alt="Previous native refinement"><figcaption>Previous refinement</figcaption></figure><figure><img loading="lazy" src="../previews/hollow-creek/{filename}" alt="Current authored native scene"><figcaption>Current authored surfaces</figcaption></figure></div>')
page+=['<h2>Individual model inspection</h2><p>Every model retains its original editable UV layers. A new1024px atlas carries the authored surface colors; the GLB uses it as UV channel0 for the unchanged geometry reader.</p>']
for a in r['assets']:
    id=a['id'];old=a['previous_source'];title=html.escape(id.replace('level_camp_','').replace('level_trace_','').replace('_authored','').replace('_',' '))
    page.append(f'<h3>{title}</h3><div class="compare"><figure><img loading="lazy" src="../previews/{old}.png" alt="Previous model"><figcaption>Previous model</figcaption></figure><figure><img loading="lazy" src="../previews/{id}.png" alt="Authored model"><figcaption>Authored surface · {a["triangles"]} unchanged triangles · <a href="../blender/{id}.blend">editable source</a> · <a href="../../../assets/runtime/models/{id}.glb">runtime GLB</a></figcaption></figure></div>')
page+=['<h2>Verification and remaining work</h2><p>14 source/GLB families reimport successfully under the unchanged50k-triangle/4MB caps;97186 triangles combined. All803 native mesh objects have identical vertices, face connectivity, smoothing flags, transforms and original UVs. The game loader passes1008 independent GLB/PNG pixel and UV checks. Eight legacy equipment source meshes still pass their loader test. A separate vehicle color-count assertion also fails against the previous committed loader; it is recorded as an existing open issue, not a passed check.</p><p class="gate">Tent, shrub, culvert/revetment and dock cable families retain the previous refined iteration. This pass improves material authorship and retains earlier construction/smoothing; it does not complete every silhouette, foliage/terrain art, gameplay, containment, circuits, layered water, loose physics, human art or performance gate.</p><p><a href="hollow-creek-authored.blend">Current native scene</a> · <a href="authored-surfaces.json">Asset/placement manifest</a> · <a href="../verification/hollow-creek-authored-surfaces.json">Independent native checks</a> · <a href="REFINEMENT_REVIEW.html">Previous refinement</a> · <a href="../../../beckenburg-development-gallery.html">Shared gallery</a></p></html>']
(OUT/'AUTHORED_REVIEW.html').write_text('\n'.join(page)+'\n',encoding='utf-8')
for filename in ['EXPANDED_REVIEW.html','REFINEMENT_REVIEW.html']:
    p=OUT/filename;text=p.read_text(encoding='utf-8');banner='<p class="gate"><a href="AUTHORED_REVIEW.html">Latest: third authored surface pass — current before/after review</a></p>'
    if banner not in text:text=text.replace('<h1>',banner+'<h1>',1)
    p.write_text(text,encoding='utf-8')
print('Built current native/model comparison review')
